import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);

  // Form Fields
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [subject, setSubject] = useState('');

  // 🌐 Node સර්වර් එකෙන් ගුරුවරුන්ගේ ලැයිස්තුව MySQL හරහා ලබා ගැනීම
  const fetchTeachers = async () => {
    try {
      const response = await axios.get('http://localhost:8081/teachers');
      setTeachers(response.data);
    } catch (error) {
      console.error("Error fetching teachers:", error);
    }
  };

  useEffect(() => {
    fetchTeachers();
  }, []);

  // 📝 අලුත් ගුරුවරයෙක් Database එකට එකතු කිරීම
  const handleAddTeacher = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('http://localhost:8081/add-teacher', {
        name, phone, email, subject
      });
      if (response.data.status === "Success") {
        alert("Teacher Added Successfully!");
        setShowAddForm(false);
        // Form එක හිස් කිරීම
        setName(''); setPhone(''); setEmail(''); setSubject('');
        fetchTeachers(); // Table එක update කිරීම
      }
    } catch (error) {
      alert("Error adding teacher");
    }
  };

  // Search filter එක ක්‍රියාත්මක කිරීම
  const filteredTeachers = teachers.filter(t => 
    t.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    t.subject.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)', height: '100%', display: 'flex', flexDirection: 'column' }}>
      
      {/* උඩ කොටස - Title එක සහ Add Button එක */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', flexShrink: 0 }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '22px', fontWeight: '700' }}>Manage Teachers</h2>
        <button 
          onClick={() => setShowAddForm(!showAddForm)}
          style={{ backgroundColor: '#15803d', color: '#fff', border: 'none', padding: '10px 18px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer', transition: '0.2s' }}
        >
          {showAddForm ? '← Back to List' : '+ Add New Teacher'}
        </button>
      </div>

      {/* 1. අලුත් ගුරුවරයෙක් එකතු කරන Form එක (Popup එකක් වගේ නෙමෙයි පිරිසිදුවට පේන එකක්) */}
      {showAddForm ? (
        <div style={{ maxWidth: '500px', backgroundColor: '#f8fafc', padding: '25px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
          <h3 style={{ marginTop: 0, color: '#15803d', marginBottom: '20px' }}>Register New Teacher</h3>
          <form onSubmit={handleAddTeacher} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            <div>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Full Name</label>
              <input type="text" required value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Mr. Amal Perera" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', outline: 'none' }} />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Contact Number</label>
              <input type="text" required value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="e.g. 0771234567" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', outline: 'none' }} />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Email Address</label>
              <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="e.g. amal@gmail.com" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', outline: 'none' }} />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Assigned Subject</label>
              <input type="text" required value={subject} onChange={(e) => setSubject(e.target.value)} placeholder="e.g. Mathematics" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', outline: 'none' }} />
            </div>
            <button type="submit" style={{ backgroundColor: '#15803d', color: '#fff', border: 'none', padding: '12px', borderRadius: '6px', fontWeight: '700', cursor: 'pointer', marginTop: '10px' }}>
              Register Teacher
            </button>
          </form>
        </div>
      ) : (
        // 2. ගුරුවරුන්ගේ ලැයිස්තුව පෙන්වන කොටස (Table View)
        <>
          {/* Search Bar */}
          <div style={{ marginBottom: '15px', flexShrink: 0 }}>
            <input 
              type="text" 
              placeholder="🔍 Search by Lecturer Name or Subject..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{ width: '100%', maxWidth: '400px', padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '14px' }}
            />
          </div>

          {/* Table Element */}
          <div style={{ flex: 1, overflowY: 'auto', border: '1px solid #e2e8f0', borderRadius: '8px' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b' }}>Full Name</th>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b' }}>Subject</th>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b' }}>Email Address</th>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b' }}>Contact Number</th>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b', textAlign: 'center' }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredTeachers.length > 0 ? (
                  filteredTeachers.map((teacher, index) => (
                    <tr key={index} style={{ borderBottom: '1px solid #f1f5f9', backgroundColor: index % 2 === 0 ? '#fff' : '#f8fafc' }}>
                      <td style={{ padding: '12px 16px', fontSize: '14px', color: '#334155', fontWeight: '500' }}>{teacher.name}</td>
                      <td style={{ padding: '12px 16px', fontSize: '14px', color: '#334155' }}>
                        <span style={{ backgroundColor: '#e0f2fe', color: '#0369a1', padding: '3px 8px', borderRadius: '4px', fontSize: '12px', fontWeight: '600' }}>{teacher.subject}</span>
                      </td>
                      <td style={{ padding: '12px 16px', fontSize: '14px', color: '#64748b' }}>{teacher.email}</td>
                      <td style={{ padding: '12px 16px', fontSize: '14px', color: '#64748b' }}>{teacher.phone_number}</td>
                      <td style={{ padding: '12px 16px', textAlign: 'center' }}>
                        <button style={{ background: 'none', border: 'none', color: '#2563eb', cursor: 'pointer', fontWeight: '600', marginRight: '10px', fontSize: '13px' }}>✏️ Edit</button>
                        <button style={{ background: 'none', border: 'none', color: '#dc2626', cursor: 'pointer', fontWeight: '600', fontSize: '13px' }}>🗑️ Delete</button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" style={{ padding: '20px', textAlign: 'center', color: '#94a3b8', fontSize: '14px' }}>No lecturers found.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}
